---@param idolLive3D_SuperTimeLineState_ table
function SuperTimelineV2_15200850_ChangeHairColor:__init( idolLive3D_SuperTimeLineState_ )
    self.SuperTimeLineState = idolLive3D_SuperTimeLineState_

    ---
    self.startTime = nil
    self.endTime = nil

    local roleTF = self.SuperTimeLineState.roleAnimator.transform
    local ears_BlendTF = roleTF:Find("Unity_Export_Grp/Geometry/ears_Blend")
    local hair_BlendTF = roleTF:Find("Unity_Export_Grp/Geometry/hair_Blend")
    assert( isNotNull(ears_BlendTF) and isNotNull(hair_BlendTF) )
    local ears_Render = KTool.GetComponent(ears_BlendTF.gameObject, typeof(SkinnedMeshRenderer))
    local hair_Render = KTool.GetComponent(hair_BlendTF.gameObject, typeof(SkinnedMeshRenderer))
    self.earsMat = ears_Render.material
    self.hairMat = hair_Render.material

end

-- 需手动调用 Delete()
function SuperTimelineV2_15200850_ChangeHairColor:__delete() 
end


function SuperTimelineV2_15200850_ChangeHairColor:StartPlay() 
    self.startTime = Time.time + LocalStartTimePoint
    self.endTime = Time.time + LocalEndTimePoint
end


function SuperTimelineV2_15200850_ChangeHairColor:AfterEndProcess() 
    self.startTime = nil
    self.endTime = nil
end



function SuperTimelineV2_15200850_ChangeHairColor:SelfUpdate() 
    
    local timelineEnv = self.SuperTimeLineState.timelineEnvMaps[self.SuperTimeLineState.currentClipId].main
    local clipJson = self.SuperTimeLineState:_FindClipJson(self.SuperTimeLineState.currentClipId)
    self.SuperTimeLineState:UpdateLeaveInfos(    clipJson, timelineEnv )
    self.SuperTimeLineState:UpdateNextClipInfos( clipJson, timelineEnv )


    if isNotNull(self.startTime) then 
        local t = Mathf.Clamp01( KTool.Remap( self.startTime, self.endTime, 0.0, 1.0, Time.time ))
        local w = KTool.Remap( 0.0, 1.0, 0.0, 2.0, t ) -- 0:黄色; 2:蓝黑色
        --print("w = " .. tostring(w))
        self.earsMat:SetFloat( "_HairBlend", w )
        self.hairMat:SetFloat( "_HairBlend", w )
    end

end





return SuperTimelineV2_15200850_ChangeHairColor
